PKWT_COMPENSATION.eligibility:
// PP 35/2021 arts.15-17: Indonesian PKWT worker with >=1 completed month of actual service (min of actual exit and signed term end).
const employment = ctx.subject.employment;
const end = get(employment, 'effective_range.to', null);
const signedEnd = get(employment, 'signed_contract_period.to', null);
if (end != null && !(ctx.entry.incurred_on <= end)) return false;
if (get(employment, 'terms.rate.amount', null) == null) return false;
if (signedEnd == null) return false;
const actualEnd = end != null && end < signedEnd ? end : signedEnd;
if (calendar_completed_months(get(employment, 'signed_contract_period.from', employment.effective_range.from), actualEnd) < 1) return false;
return get(employment, 'payroll.nationality', 'ID') === 'ID';

PKWT_COMPENSATION.conversion:
// PP 35/2021 art.16-17: 1 month wage per 12 months of actual service (min of effective_range.to and signed_contract_period.to); partial month /30.
const terms = get(ctx.subject.employment, 'terms', {});
const monthly = get(get(terms, 'rate', {}), 'unit', 'MONTHLY') === 'DAILY'
	? ctx.day_rate * 30 + (ctx.month_wage - ctx.day_rate * ctx.working_days)
	: ctx.month_wage;
const agreed = get(ctx.subject.employment, 'statutory_parameters.agreed_pkwt_compensation_amount', null);
if (get(ctx.subject.employment, 'statutory_parameters.micro_small_enterprise', false) && agreed != null) return agreed;
const effEnd = get(ctx.subject.employment, 'effective_range.to', null);
const signedEnd = get(ctx.subject.employment, 'signed_contract_period.to', null);
const end = (effEnd != null && signedEnd != null) ? (effEnd < signedEnd ? effEnd : signedEnd) : (effEnd ?? signedEnd ?? ctx.as_of);
const start = get(ctx.subject.employment, 'signed_contract_period.from', ctx.subject.employment.effective_range.from);
const completed = calendar_completed_months(start, end);
const months = completed + calendar_distance_days(add_months(start, completed), end) / 30;
return monthly * months / 12;

