	Number(get(ctx.statutory, 'JKK.employer', 0)) +
	Number(get(ctx.statutory, 'JKM.employer', 0)) +
	Number(get(ctx.statutory, 'KESEHATAN.employer', 0)) +
	Number(get(ctx.posted, 'BENEFIT.employer', 0));
// art.5(3)(d)–(e) puts employer premiums in a permanent employee's income only.
const current = casual ? wages : wages + premiums;
const surcharge = get(facts, 'tax_id_validated', true) === false ? ctx.lookup.missing_tax_id_multiplier : 1;
const periodEnd = String(get(get(ctx.run, 'salary_coverage', {}), 'to', ctx.as_of));
// balances close by pay date, so the tax year and its last period do too
const payDate = String(get(ctx.run, 'pay_date', ctx.as_of));
const taxYear = payDate.slice(0, 4);
const yearStart = taxYear + '-01-01';
const subjectFrom = String(get(facts, 'tax_subject_from', ''));
const subjectUntil = String(get(facts, 'tax_subject_until', ''));
const arrived = subjectFrom.slice(0, 4) === taxYear && subjectFrom.slice(5, 7) > '01';
const leaving = subjectUntil.slice(0, 4) === taxYear && subjectUntil.slice(5, 7) < '12';
// art.9(4)–(5): PTKP stands as at 1 January, or the first of a new resident's arrival month.
const standingDate = arrived ? month_start(subjectFrom) : yearStart;
const standings = get(facts, 'ptkp_standings', []).filter((row) => get(row, 'as_of', '') === standingDate);
if (standings.length > 1) throw 'Two PTKP standings on ' + standingDate + '.';
const standing = first(standings);
const marital = get(employment, 'payroll.marital_status', 'SINGLE');
const gender = get(employment, 'payroll.gender', '');
const husband = get(standing, 'husband_no_income_certified', get(employment, 'family', []).some((member) => member.relation === 'SPOUSE' && get(member, 'has_income', null) === false)) === true;
const marriedFemale = marital === 'MARRIED' && gender === 'FEMALE' && !husband;
const dependents = Math.min(
	Math.max(0, Math.trunc(Number(get(standing, 'ptkp_dependents_count', get(employment, 'family', []).filter((member) => member.relation !== 'SPOUSE' && get(member, 'has_income', null) !== true).length)))),
	ctx.lookup.maximum_dependants
);
const status = marriedFemale ? 'TK/0' : (marital === 'MARRIED' ? 'K/' : 'TK/') + String(dependents);
const category = get(ctx.lookup.ptkp_ter_table, status, '1');
const table = category === '1' ? ctx.lookup.ter_1 : category === '2' ? ctx.lookup.ter_2 : ctx.lookup.ter_3;
// PMK 168/2023 art.5(1): the month's gross is all its regular and irregular pay, so a month's runs are one month of income.
const heldMonth = get(ctx, 'balances.month', {});
const heldIn = (code) => {
	const key = payDate.slice(0, 7) + '.' + code;
	return Object.hasOwn(heldMonth, key) ? Number(heldMonth[key]) : 0;
};
const coverage = ctx.run.salary_coverage;
const wholeMonth =
	String(coverage.from) === String(month_start(coverage.from)) && String(coverage.to) === String(month_end(coverage.from));
const separate = get(ctx.run, 'kind', '') !== 'OFF_CYCLE' && wholeMonth && heldIn('BASIC') > 0;
const before = (code) => (separate ? 0 : heldIn(code));
const monthGross =
	current +
	before('ADDITIONAL_WAGES') +
	(casual ? 0 : before('JKK.employer') + before('JKM.employer') + before('KESEHATAN.employer'));
const monthly =
	round(bracket(monthGross, table) * monthGross * surcharge, ctx.lookup.whole_unit, 'HALF_UP') - before('PPH21.employee');
const cadence = get(facts, 'pph21_payment_cadence', 'MONTHLY');
// arts.12(2), 16(2): no non-permanent worker has a year-end reckoning.
if (casual && cadence === 'MONTHLY') return monthly;
if (casual) {
	const worked = get(ctx, 'work.days', []).filter((day) => get(day, 'worked', false) === true).length;
	const rate = Number(get(terms, 'rate.amount', 0));
	const paidDays = unit === 'DAILY' && rate > 0 ? Number(get(ctx.subtotals, 'BASIC', 0)) / rate : 1;
	const days = worked > 0 ? worked : Math.max(1, paidDays);
	const perDay = current / days;
	if (perDay <= ctx.lookup.daily_ter_ceiling)
		return round(bracket(perDay, ctx.lookup.ter_daily) * current * surcharge, ctx.lookup.whole_unit, 'HALF_UP');
	return round(ladder(perDay * ctx.lookup.daily_taxable_share, ctx.lookup.annual_ladder) * days * surcharge, ctx.lookup.whole_unit, 'HALF_UP');
}
const exit = get(employment, 'effective_range.to', null);
// December reckons the year on its salary: an off-cycle run ahead of that salary is not the last period.
const december = payDate.slice(5, 7) === '12' && (get(ctx.run, 'kind', '') !== 'OFF_CYCLE' || before('ORDINARY_WAGES') > 0);
const last = december || (exit != null && exit <= periodEnd) || (leaving && subjectUntil <= periodEnd);
if (!last) return monthly;
const ptkp = ctx.lookup.ptkp_amount[status];
const employedFrom = get(employment, 'service_started_on', get(employment, 'effective_range.from', yearStart));
const joined = employedFrom > yearStart ? employedFrom : yearStart;
const opening = arrived && subjectFrom > joined ? subjectFrom : joined;
const closing = [exit, leaving ? subjectUntil : null].reduce(
	(end, date) => (date != null && date < end ? date : end),
	payDate
);
const months = Math.min(
	12,
	Math.max(
		1,
		(Number(closing.slice(0, 4)) - Number(opening.slice(0, 4))) * 12 +
			Number(closing.slice(5, 7)) -
			Number(opening.slice(5, 7)) +
			1
	)
);
const paid = (code) => {
	const held = get(ctx.balances, 'statutory_contribution', {});
	return Object.hasOwn(held, code) ? held[code] : 0;
};
const annualGross =
	Number(get(ctx.balances, 'ytd.ADDITIONAL_WAGES', 0)) +
	paid('JKK.employer') +
	paid('JKM.employer') +
	paid('KESEHATAN.employer') +
	// the year's benefits in kind, as each month taxed them; this run's entry is already in `current`
	paid('BENEFIT.employer') -
	Number(get(ctx.posted, 'BENEFIT.employer', 0)) +
	current;
const expense = Math.min(
	annualGross * ctx.lookup.employment_expense_share,
	ctx.lookup.monthly_employment_expense_limit * months
);
const contributions =
	paid('JHT.employee') +
	paid('JP.employee') +
	Number(get(ctx.statutory, 'JHT.employee', 0)) +
	Number(get(ctx.statutory, 'JP.employee', 0));
const ownDeductions = (Number(get(facts, 'dplk_employee_monthly', 0)) + Number(get(facts, 'zakat_monthly', 0))) * months;
const net = annualGross - expense - contributions - ownDeductions;
// art.15(3): a part-year resident's net income is annualised and the tax taken back to the months.
// PMK 168/2023 art.15(3) & Lampiran Contoh I.6: annualize on mid-year arrival, emigration, or DEATH; use actual months worked on mid-year exit.
const died = get(facts, 'exit_ground', get(facts, 'termination_cause', '')) === 'DEATH' && exit != null && exit.slice(0, 4) === taxYear;
const partYear = arrived || leaving || died;
const partMonths = partYear ? months : 12;
const taxable = Math.max(0, (partYear ? (net * 12) / partMonths : net) - ptkp);
const yearTax = ladder(round(taxable, ctx.lookup.thousand_units, 'DOWN'), ctx.lookup.annual_ladder);
const due = round((partYear ? (yearTax * partMonths) / 12 : yearTax) * surcharge, ctx.lookup.whole_unit, 'HALF_UP');
const withheld = paid('PPH21.employee');
// art.21(1)–(2): the excess goes back, never the part the government bore.
if (due >= withheld) return due - withheld;
return -Math.min(withheld - due, withheld - paid('PPH21_DTP.employer'));

PPH21_DTP.eligibility:
// PMK 10/2025 & PMK 105/2025 arts.2-4: eligible KLU, validated NPWP/NIK, pay_date tax_year; non-permanent daily average <=Rp500k (no ref gross needed), permanent ref gross <=Rp10M.
const employment = ctx.subject.employment;
const terms = get(employment, 'terms', {});
const facts = get(employment, 'statutory_parameters', {});
if (employment.engagement === 'PAYEE') return false;
if (!['CITIZEN', 'RESIDENT_FOREIGNER'].includes(get(terms, 'residency_status', ''))) return false;
if (get(facts, 'tax_id_validated', false) !== true) return false;
const entity = get(ctx.subject.employer, 'statutory_parameters', {});
if (!ctx.lookup.eligible_klu.includes(get(entity, 'klu', ''))) return false;
const payDate = String(get(ctx.run, 'pay_date', ctx.run.salary_coverage.from));
if (Number(payDate.slice(0, 4)) !== ctx.lookup.tax_year) return false;
const unit = get(get(terms, 'rate', {}), 'unit', 'MONTHLY');
const nonPerm = ['DAILY', 'HOURLY'].includes(unit) || ['PIECE_RATE', 'TASK_BASIS'].includes(get(terms, 'statutory_work_category', '')) || get(employment, 'engagement', '') === 'PART_TIME';
const nonMonthly = nonPerm && get(facts, 'pph21_payment_cadence', 'NON_MONTHLY') !== 'MONTHLY';
if (nonMonthly) {
	const worked = get(ctx, 'work.days', []).filter((d) => get(d, 'worked', false) === true).length;
	const rate = Number(get(terms, 'rate.amount', 0));
	const paidDays = unit === 'DAILY' && rate > 0 ? Number(get(ctx.subtotals, 'BASIC', 0)) / rate : 1;
	const days = worked > 0 ? worked : Math.max(1, paidDays);
	return (Number(get(ctx.subtotals, 'ORDINARY_WAGES', 0)) / days) <= ctx.lookup.daily_average_income_ceiling;
}
const reference = get(facts, 'pph21_dtp_reference_gross', null);
const referenceYear = get(facts, 'pph21_dtp_reference_year', null);
if (reference == null || Number(referenceYear) !== ctx.lookup.tax_year) return false;
return Number(reference) <= ctx.lookup.monthly_regular_income_ceiling;

PPH21_DTP.employee_amount:
// PMK 105/2025 art.5(1),(5): government-borne tax offsets positive PPh 21 only (never turns a Dec refund into a deduction).
const pph21 = Math.max(0, Number(get(ctx.statutory, 'PPH21.employee', 0)));
return pph21 === 0 ? 0 : -pph21;

PPH21_FINAL_SEVERANCE.eligibility:
const employment = ctx.subject.employment;
const terms = get(employment, 'terms', {});
const facts = get(employment, 'statutory_parameters', {});
if (employment.engagement === 'PAYEE') return false;
if (!['CITIZEN', 'RESIDENT_FOREIGNER'].includes(get(terms, 'residency_status', ''))) return false;
if (ctx.subtotals.SEVERANCE === ctx.subtotals.ADDITIONAL_WAGES) return false;
const year = Number(String(get(ctx.run, 'pay_date', ctx.as_of)).slice(0, 4));
const years = get(ctx, 'balances.years', {});
const paidBefore = Object.keys(years).some((key) => Number(key) < year && Number(get(years[key], 'SEVERANCE', 0)) > Number(get(years[key], 'ADDITIONAL_WAGES', 0)));
// PP 68/2009 arts.2(2), 5, 6: the year of the first payment decides final or not. With none paid in an earlier year, this payment is the first.
const firstYear = get(facts, 'severance_tax_history.first_payment_year', paidBefore ? null : year);
if (firstYear == null) throw 'Record severance_tax_history.first_payment_year: part of this benefit was paid in an earlier year.';
if (firstYear < year - 1) return false;
return firstYear <= year;

PPH21_FINAL_SEVERANCE.employee_amount:
// PP 68/2009: the ladder falls on the benefit paid, so one month's runs are one payment: what an earlier run of this month paid is in the balance.
const month = get(ctx, 'balances.month', {});
const paidMonth = String(get(ctx.run, 'pay_date', ctx.run.salary_coverage.from)).slice(0, 7);
const heldIn = (code) => (Object.hasOwn(month, paidMonth + '.' + code) ? Number(month[paidMonth + '.' + code]) : 0);
const coverage = ctx.run.salary_coverage;
const wholeMonth =
	String(coverage.from) === String(month_start(coverage.from)) && String(coverage.to) === String(month_end(coverage.from));
const separate = get(ctx.run, 'kind', '') !== 'OFF_CYCLE' && wholeMonth && heldIn('BASIC') > 0;
const before = (code) => (separate ? 0 : heldIn(code));
// PP 68/2009 arts.2(2), 6: the first two calendar years are one benefit. What each earlier year paid stays on the balance.
const years = get(ctx, 'balances.years', {});
const firstYear = String(get(ctx.subject.employment, 'statutory_parameters.severance_tax_history.first_payment_year', ''));
const held = (code) => sum(Object.keys(years).filter((key) => key >= firstYear && key <= paidMonth.slice(0, 4)).map((key) => (Object.hasOwn(years[key], code) ? Number(years[key][code]) : 0)));
const earlier = (code) => held(code) - heldIn(code);
const base = Math.max(0, ctx.subtotals.SEVERANCE + before('SEVERANCE') - ctx.subtotals.ADDITIONAL_WAGES - before('ADDITIONAL_WAGES') + earlier('SEVERANCE') - earlier('ADDITIONAL_WAGES'));
return round(ladder(base, ctx.lookup.ladder), ctx.lookup.whole_unit, 'HALF_UP') - before('PPH21_FINAL_SEVERANCE.employee') - earlier('PPH21_FINAL_SEVERANCE.employee');

PPH21_FINAL_PENSION.eligibility:
const employment = ctx.subject.employment;
const terms = get(employment, 'terms', {});
const facts = get(employment, 'statutory_parameters', {});
if (employment.engagement === 'PAYEE') return false;
if (!['CITIZEN', 'RESIDENT_FOREIGNER'].includes(get(terms, 'residency_status', ''))) return false;
if (ctx.subtotals.PENSION_BENEFIT === ctx.subtotals.SEVERANCE) return false;
const year = Number(String(get(ctx.run, 'pay_date', ctx.as_of)).slice(0, 4));
const years = get(ctx, 'balances.years', {});
const paidBefore = Object.keys(years).some((key) => Number(key) < year && Number(get(years[key], 'PENSION_BENEFIT', 0)) > Number(get(years[key], 'SEVERANCE', 0)));
// PP 68/2009 arts.2(2), 5, 6: the year of the first payment decides final or not. With none paid in an earlier year, this payment is the first.
const firstYear = get(facts, 'pension_tax_history.first_payment_year', paidBefore ? null : year);
if (firstYear == null) throw 'Record pension_tax_history.first_payment_year: part of this benefit was paid in an earlier year.';
if (firstYear < year - 1) return false;
return firstYear <= year;

PPH21_FINAL_PENSION.employee_amount:
// PP 68/2009: the ladder falls on the benefit paid, so one month's runs are one payment: what an earlier run of this month paid is in the balance.
const month = get(ctx, 'balances.month', {});
const paidMonth = String(get(ctx.run, 'pay_date', ctx.run.salary_coverage.from)).slice(0, 7);
const heldIn = (code) => (Object.hasOwn(month, paidMonth + '.' + code) ? Number(month[paidMonth + '.' + code]) : 0);
const coverage = ctx.run.salary_coverage;
const wholeMonth =
	String(coverage.from) === String(month_start(coverage.from)) && String(coverage.to) === String(month_end(coverage.from));
const separate = get(ctx.run, 'kind', '') !== 'OFF_CYCLE' && wholeMonth && heldIn('BASIC') > 0;
const before = (code) => (separate ? 0 : heldIn(code));
// PP 68/2009 arts.2(2), 6: the first two calendar years are one benefit. What each earlier year paid stays on the balance.
const years = get(ctx, 'balances.years', {});
const firstYear = String(get(ctx.subject.employment, 'statutory_parameters.pension_tax_history.first_payment_year', ''));
const held = (code) => sum(Object.keys(years).filter((key) => key >= firstYear && key <= paidMonth.slice(0, 4)).map((key) => (Object.hasOwn(years[key], code) ? Number(years[key][code]) : 0)));
const earlier = (code) => held(code) - heldIn(code);
const base = Math.max(0, ctx.subtotals.PENSION_BENEFIT + before('PENSION_BENEFIT') - ctx.subtotals.SEVERANCE - before('SEVERANCE') + earlier('PENSION_BENEFIT') - earlier('SEVERANCE'));
return round(ladder(base, ctx.lookup.ladder), ctx.lookup.whole_unit, 'HALF_UP') - before('PPH21_FINAL_PENSION.employee') - earlier('PPH21_FINAL_PENSION.employee');

PPH21_BUKAN_PEGAWAI.eligibility:
// PMK 168/2023 arts.12(3)–(4), 13: eligibility gate.
const employment = ctx.subject.employment;
const terms = get(employment, 'terms', {});
if (employment.engagement !== 'PAYEE') return false;
if (!['CITIZEN', 'RESIDENT_FOREIGNER'].includes(get(terms, 'residency_status', ''))) return false;
return ctx.subtotals.ADDITIONAL_WAGES !== 0;

PPH21_BUKAN_PEGAWAI.employee_amount:
// PMK 168/2023 arts.12(3), 16(3): each separate non-employee payment is taxed independently at 50% x gross x Pasal 17 (no same-month cumulation).
const facts = get(ctx.subject.employment, 'statutory_parameters', {});
const surcharge = get(facts, 'tax_id_validated', true) === false ? ctx.lookup.missing_tax_id_multiplier : 1;
const base = Math.max(0, Number(ctx.subtotals.ADDITIONAL_WAGES)) * ctx.lookup.taxable_income_share;
return round(ladder(base, ctx.lookup.annual_ladder) * surcharge, ctx.lookup.whole_unit, 'HALF_UP');

PPH26.eligibility:
// UU 36/2008 (PPh) art.26(1)(d), art.2(4), art.21(1), art.21(5a): eligibility gate.
return get(get(ctx.subject.employment, 'terms', {}), 'residency_status', '') === 'NON_RESIDENT' &&
	ctx.subtotals.GROSS !== 0;

PPH26.employee_amount:
// UU 36/2008 (PPh) art.26(1)(d), art.2(4), art.21(1), art.21(5a): employee statutory calculation.
const facts = get(ctx.subject.employment, 'statutory_parameters', {});
const rate = Number(get(facts, 'pph26_treaty_rate', ctx.lookup.ordinary_rate));
return round(ctx.subtotals.GROSS * rate, ctx.lookup.whole_unit, 'HALF_UP');

DKPTKA.eligibility:
// PP 34/2021 arts.1 angka 7, 23, 25: eligibility gate.
const employment = ctx.subject.employment;
const facts = get(employment, 'statutory_parameters', {});
const nationality = get(employment, 'payroll.nationality', 'ID');
if (employment.engagement === 'PAYEE') return false;
if (nationality === '') return false;
if (nationality === 'ID') return false;
return get(facts, 'dkptka_exempt', false) !== true;

DKPTKA.employer_amount:
// PP 34/2021 arts.1 angka 7, 23, 25: employer statutory calculation.
const rate = get(ctx.subject.employer, 'statutory_parameters.dkptka_usd_idr_rate', null);
return rate == null ? 0 : ctx.lookup.monthly_usd * Number(rate);

PPH21_BENEFIT_NONFINAL.eligibility:
// PP 68/2009; PMK 16/PMK.03/2010 PP 68/2009 art.6; PMK 16/PMK.03/2010 art.5(1)–(3); benefit first payment year: eligibility gate.
const employment = ctx.subject.employment;
const terms = get(employment, 'terms', {});
const facts = get(employment, 'statutory_parameters', {});
if (employment.engagement === 'PAYEE') return false;
if (!['CITIZEN', 'RESIDENT_FOREIGNER'].includes(get(terms, 'residency_status', ''))) return false;
const severance = Number(get(facts, 'severance_tax_history.first_payment_year', 0));
const pension = Number(get(facts, 'pension_tax_history.first_payment_year', 0));
const firstYear = Math.max(severance, pension);
const year = Number(String(get(ctx.run, 'pay_date', ctx.as_of)).slice(0, 4));
const other = Number(get(ctx.statutory, 'PPH21.employee', 0)) +
	Number(get(ctx.statutory, 'PPH21_BUKAN_PEGAWAI.employee', 0)) +
	Number(get(ctx.statutory, 'PPH26.employee', 0));
if (!(firstYear > 0)) return false;
if (!(firstYear < year - 1)) return false;
if (other !== 0) return false;
return ctx.subtotals.PENSION_BENEFIT !== ctx.subtotals.ADDITIONAL_WAGES;

PPH21_BENEFIT_NONFINAL.employee_amount:
// PMK 16/PMK.03/2010 art.5: the ladder falls on the instalment paid, so one month's runs are one payment: what an earlier run of this month paid is in the balance.
const month = get(ctx, 'balances.month', {});
const paidMonth = String(get(ctx.run, 'pay_date', ctx.run.salary_coverage.from)).slice(0, 7);
const heldIn = (code) => (Object.hasOwn(month, paidMonth + '.' + code) ? Number(month[paidMonth + '.' + code]) : 0);
const coverage = ctx.run.salary_coverage;
const wholeMonth =
	String(coverage.from) === String(month_start(coverage.from)) && String(coverage.to) === String(month_end(coverage.from));
const separate = get(ctx.run, 'kind', '') !== 'OFF_CYCLE' && wholeMonth && heldIn('BASIC') > 0;
const before = (code) => (separate ? 0 : heldIn(code));
const base = Math.max(0, ctx.subtotals.PENSION_BENEFIT + before('PENSION_BENEFIT') - ctx.subtotals.ADDITIONAL_WAGES - before('ADDITIONAL_WAGES'));
const facts = get(ctx.subject.employment, 'statutory_parameters', {});
const surcharge = get(facts, 'tax_id_validated', true) === false ? ctx.lookup.missing_tax_id_multiplier : 1;
return round(ladder(base, ctx.lookup.annual_ladder) * surcharge, ctx.lookup.whole_unit, 'HALF_UP') - before('PPH21_BENEFIT_NONFINAL.employee');

PPH21_EMPLOYER_BORNE.eligibility:
// UU 7/1983 on Income Tax as amended by UU 7/2021 (HPP); PMK 168/2023 UU 7/1983 art.21(1)(a); PMK 168/2023 art.5: eligibility gate.
if (get(ctx.subject.employment, 'terms.employer_bears_income_tax', false) !== true) return false;
return Number(get(ctx.statutory, 'PPH21.employee', 0)) + Number(get(ctx.statutory, 'PPH21_DTP.employee', 0)) !== 0;

PPH21_EMPLOYER_BORNE.employee_amount:
const employment = ctx.subject.employment;
const terms = get(employment, 'terms', {});
const tax = Number(get(ctx.statutory, 'PPH21.employee', 0)) + Number(get(ctx.statutory, 'PPH21_DTP.employee', 0));
const casual = ['DAILY', 'HOURLY'].includes(get(terms, 'rate.unit', 'MONTHLY')) ||
	['PIECE_RATE', 'TASK_BASIS'].includes(get(terms, 'statutory_work_category', '')) ||
	get(employment, 'engagement', '') === 'PART_TIME';
const premiums =
	Number(get(ctx.statutory, 'JKK.employer', 0)) +
	Number(get(ctx.statutory, 'JKM.employer', 0)) +
	Number(get(ctx.statutory, 'KESEHATAN.employer', 0)) +
	Number(get(ctx.posted, 'BENEFIT.employer', 0));
// PMK 168/2023 art.5(3)(d)–(e): a permanent employee's income carries the employer premiums.
const income = Number(get(ctx.subtotals, 'ADDITIONAL_WAGES', 0)) + (casual ? 0 : premiums);
const items = get(ctx.run, 'kind', '') === 'OFF_CYCLE'
	? 0
	: sum(get(terms, 'employee_borne_tax_items', []).map((code) => Number(get(terms, 'allowances.' + code + '.amount', 0))));
const own = income > 0 ? round((tax * Math.min(items, income)) / income, ctx.lookup.whole_unit, 'HALF_UP') : 0;
return own - tax;

PPH21_EMPLOYER_BORNE.employer_amount:
const employment = ctx.subject.employment;
const terms = get(employment, 'terms', {});
const tax = Number(get(ctx.statutory, 'PPH21.employee', 0)) + Number(get(ctx.statutory, 'PPH21_DTP.employee', 0));
const casual = ['DAILY', 'HOURLY'].includes(get(terms, 'rate.unit', 'MONTHLY')) ||
	['PIECE_RATE', 'TASK_BASIS'].includes(get(terms, 'statutory_work_category', '')) ||
	get(employment, 'engagement', '') === 'PART_TIME';
const premiums =
	Number(get(ctx.statutory, 'JKK.employer', 0)) +
	Number(get(ctx.statutory, 'JKM.employer', 0)) +
	Number(get(ctx.statutory, 'KESEHATAN.employer', 0)) +
	Number(get(ctx.posted, 'BENEFIT.employer', 0));
// PMK 168/2023 art.5(3)(d)–(e): a permanent employee's income carries the employer premiums.
const income = Number(get(ctx.subtotals, 'ADDITIONAL_WAGES', 0)) + (casual ? 0 : premiums);
const items = get(ctx.run, 'kind', '') === 'OFF_CYCLE'
	? 0
	: sum(get(terms, 'employee_borne_tax_items', []).map((code) => Number(get(terms, 'allowances.' + code + '.amount', 0))));
const own = income > 0 ? round((tax * Math.min(items, income)) / income, ctx.lookup.whole_unit, 'HALF_UP') : 0;
// Allow employer to recover December over-withheld PPh 21 that employer bore during the year.
return tax - own;

BPJS_KETENAGAKERJAAN_REMITTANCE.condition:
// PP 44/2015 arts.21–22(1) ; PP 45/2015 arts.30–31 ; PP 46/2015 (JHT: Raises the monthly BPJS Ketenagakerjaan remittance task when a payslip owes JHT, JKK, JKM or JP.
const codes = ctx.lookup.scheme_codes;
const owed = (row) => codes.includes(row.code) && (row.employee > 0 || row.employer > 0);
return ctx.reads.payslip.some((slip) => get(slip.breakdown, 'statutory', []).some(owed));

BPJS_KETENAGAKERJAAN_REMITTANCE.effects:
// PP 44/2015 arts.21–22(1) ; PP 45/2015 arts.30–31 ; PP 46/2015 (JHT: Raises the monthly BPJS Ketenagakerjaan remittance task when a payslip owes JHT, JKK, JKM or JP.
const key = occurrence_key(['ID', 'BPJS_KETENAGAKERJAAN_REMITTANCE', ctx.entry.entity_id, ctx.entry.id]);
if (ctx.reads.obligation.some((o) => o.occurrence_key === key)) return [];
return [{
  entity_id: ctx.entry.entity_id,
  title: 'BPJS Ketenagakerjaan contributions (JHT, JKK, JKM, JP)',
  due_on: add_working_days(add_days(month_end(ctx.entry.salary_coverage.from), ctx.lookup.date_offset_days - 1), 1, ctx.reads.holiday, [0, 6]),
  occurrence_key: key,
