const beforeHoliday = (h) => {
  if (!(h.date >= ctx.entry.salary_coverage.from)) return false;
  if (!(h.date <= add_months(ctx.entry.salary_coverage.to, ctx.lookup.date_offset_months))) return false;
  if (!ctx.lookup.holiday_names.some((n) => h.name.includes(n))) return false;
  if (!(add_days(h.date, -notice) >= ctx.entry.salary_coverage.from)) return false;
  return add_days(h.date, -notice) <= ctx.entry.salary_coverage.to;
};
const matched = ctx.reads.holiday.filter(beforeHoliday);
if (matched.length === 0) return [];
const key = occurrence_key(['ID', 'THR_PAYMENT', ctx.entry.entity_id, ctx.entry.period]);
if (ctx.reads.obligation.some((o) => o.occurrence_key === key)) return [];
return [{
