// Permenaker 6/2016 arts.5(4), 10(1): THR is due H-7 before the religious holiday; paying H-6..H-1 or after holiday triggers 5% fine.
if (!['THR', 'THR_HOLIDAY'].includes(ctx.entry.catalog_code)) return false;
const matchHoliday = (h) => {
	if (!(h.date >= add_days(ctx.entry.incurred_on, -60) && h.date <= add_days(ctx.entry.incurred_on, 60))) return false;
	return ctx.lookup.holiday_names.some((n) => h.name.includes(n));
};
const near = ctx.reads.holiday.filter(matchHoliday).toSorted((a, b) =>
	Math.abs(calendar_distance_days(a.date, ctx.entry.incurred_on)) - Math.abs(calendar_distance_days(b.date, ctx.entry.incurred_on))
)[0];
return near != null && ctx.entry.incurred_on > add_days(near.date, -ctx.lookup.advance_notice_days);

