}
return true;

PESANGON.conversion:
const terms = get(ctx.subject.employment, 'terms', {});
// a daily wage's month is 30 days' wage (UU 27/2026 art.234(2)); month_wage is salary plus fixed allowances, so a day rate's allowance part is the difference
const monthly =
	get(get(terms, 'rate', {}), 'unit', 'MONTHLY') === 'DAILY'
		? ctx.day_rate * 30 + (ctx.month_wage - ctx.day_rate * ctx.working_days)
		: ctx.month_wage;

// art.157(4) as amended: a month below the worksite minimum wage counts at the minimum wage (not for a micro or small enterprise)
const facts = get(ctx.subject.employer, 'statutory_parameters', {});
const region = get(ctx.subject.employment, 'terms.work_region', '') || get(facts, 'region', '');
const floor = get(facts, 'enterprise_size_class', '') === 'MICRO_OR_SMALL' ? 0 : get(ctx.lookup.by_region, region, 0);
const wage = Math.max(monthly, floor);
const months = calendar_completed_months(get(ctx.subject.employment, 'service_started_on', ctx.subject.employment.effective_range.from), get(ctx.subject.employment, 'effective_range.to', null) ?? ctx.as_of);
const agreed = get(ctx.subject.employment, 'statutory_parameters.agreed_pesangon_amount', null);
if (get(ctx.subject.employment, 'statutory_parameters.micro_small_enterprise', false) && agreed != null) return agreed;
const cause = String(get(ctx.subject.employment, 'statutory_parameters.termination_cause', null));
// every listed cause has its factor in the lookup
return wage * bracket(months, ctx.lookup.schedule) * get(ctx.lookup.cause_multiplier, cause, 1);

UPMK.conversion:
const terms = get(ctx.subject.employment, 'terms', {});
// a daily wage's month is 30 days' wage (UU 27/2026 art.234(2)); month_wage is salary plus fixed allowances, so a day rate's allowance part is the difference
const monthly =
	get(get(terms, 'rate', {}), 'unit', 'MONTHLY') === 'DAILY'
		? ctx.day_rate * 30 + (ctx.month_wage - ctx.day_rate * ctx.working_days)
		: ctx.month_wage;

// art.157(4) as amended: a month below the worksite minimum wage counts at the minimum wage (not for a micro or small enterprise)
const facts = get(ctx.subject.employer, 'statutory_parameters', {});
const region = get(ctx.subject.employment, 'terms.work_region', '') || get(facts, 'region', '');
const floor = get(facts, 'enterprise_size_class', '') === 'MICRO_OR_SMALL' ? 0 : get(ctx.lookup.by_region, region, 0);
const wage = Math.max(monthly, floor);
const months = calendar_completed_months(get(ctx.subject.employment, 'service_started_on', ctx.subject.employment.effective_range.from), get(ctx.subject.employment, 'effective_range.to', null) ?? ctx.as_of);
const agreed = get(ctx.subject.employment, 'statutory_parameters.agreed_upmk_amount', null);
if (get(ctx.subject.employment, 'statutory_parameters.micro_small_enterprise', false) && agreed != null) return agreed;
const cause = String(get(ctx.subject.employment, 'statutory_parameters.termination_cause', null));
// UU 27/2026 arts.238, 246: the UPMK factor of the cause, 1 unless the lookup names another
return wage * bracket(months, ctx.lookup.schedule) * get(ctx.lookup.cause_multiplier, cause, 1);

LKS_BIPARTIT_FORMATION.effects:
// UU 27/2026 art.171(1)-(2): non-micro/small enterprises with >=10 workers must form LKS Bipartit.
if (get(ctx.subject.employer, 'statutory_parameters.lks_bipartit_formed_on', null) != null) return [];
if (get(ctx.subject.employer, 'statutory_parameters.enterprise_size_class', '') === 'MICRO_OR_SMALL') return [];
const onPayroll = (c) => {
	if (get(c, 'engagement', null) === 'PAYEE') return false;
	if (!(c.effective_range.from <= ctx.entry.salary_coverage.to)) return false;
	return c.effective_range.to == null || c.effective_range.to >= ctx.entry.salary_coverage.from;
};
if (ctx.reads.employment.filter(onPayroll).length < ctx.lookup.employee_count_threshold) return [];
const key = occurrence_key(['ID', 'LKS_BIPARTIT_FORMATION', ctx.entry.entity_id, ctx.entry.period]);
if (ctx.reads.obligation.some((o) => o.occurrence_key === key)) return [];
return [{
	entity_id: ctx.entry.entity_id,
	title: 'Form bipartite cooperation body (LKS Bipartit, >=10 workers)',
	due_on: month_end(ctx.entry.salary_coverage.from),
	occurrence_key: key,
}];

K3_SMK3_P2K3.effects:
// UU 27/2026 arts.130(3), 131(1), 307: every employer forms Komite K3; SMK3 mandatory for >=100 workers or high hazard.
const key = occurrence_key(['ID', 'K3_SMK3_P2K3', ctx.entry.entity_id]);
if (ctx.reads.obligation.some((o) => o.occurrence_key === key)) return [];
return [{
	entity_id: ctx.entry.entity_id,
	title: 'Establish Komite K3 (and SMK3 if >=100 workers or high hazard)',
	due_on: month_end(ctx.entry.salary_coverage.from),
	occurrence_key: key,
}];
